// A hidden class is modeled by the ORDERED key list a construction path produces.
// distinctShapes(builder) returns how many distinct ordered-key signatures appear.
function shapeSig(o) {
  // Object.keys preserves insertion order for string keys -> models the transition path.
  return Object.keys(o).join(',');
}
function distinctShapes(builder, n) {
  const seen = new Set();
  for (let i = 0; i < n; i++) seen.add(shapeSig(builder(i)));
  return seen.size;
}

// CONSISTENT: same assignment order every time -> one transition path.
function consistent(i) {
  const o = {};
  o.x = i; o.y = i + 1; o.z = i + 2;
  return o;
}

// SCRAMBLED: assignment order depends on i, plus a late-added field on some.
function scrambled(i) {
  const o = {};
  const order = [['x', i], ['y', i + 1], ['z', i + 2]];
  // rotate the order based on i -> different first-added property each time
  for (let k = 0; k < 3; k++) {
    const [key, val] = order[(i + k) % 3];
    o[key] = val;
  }
  if (i % 2 === 0) o.w = i; // late field added only to some objects
  return o;
}

const mono = distinctShapes(consistent, 6);
const mega = distinctShapes(scrambled, 6);
console.log('consistent=' + mono + ' scrambled=' + mega);

